from pathlib import Path
p=Path('src/server/repositories/organization-repository.ts');s=p.read_text().replace('isNull, like }','isNull, like, ne }').replace('eq(members.status, \"active\"),','ne(members.status, \"suspended\"),');p.write_text(s)
p=Path('tests/services/member-service.test.ts');s=p.read_text().replace('createTenant, useTemporaryDatabase','createTenant, issueInput, useTemporaryDatabase');s=s.replace('import type { Unsubscribe }','''import * as orgRepo from \"@/server/repositories/organization-repository\";
