import * as commentService from \"@/server/services/comment-service\";
import { notify } from \"@/server/services/notification-service\";
import { buildDigest } from \"@/server/services/digest-service\";
import { registerActivityListeners } from \"@/server/services/activity-service\";
import * as activityRepo from \"@/server/repositories/activity-repository\";
import { NotFoundError } from \"@/server/services/_support\";
import { TenantScopeError } from \"@/lib/tenant\";
import { toIsoTimestamp } from \"@/types/common\";
import type { Unsubscribe }''');s+='''

describe(\"member suspension\", () => {
  it(\"retains membership and seats, blocks participation, and reverses on reinstatement\", async () => {
    const tenant = await createTenant(\"suspension-lifecycle\", \"growth\");
    const target = (await memberRepo.findMember(tenant.org.id, tenant.userIds.member))"'!;
    const orgId = tenant.org.id;
    const actor = tenant.actors.owner;
    const input = { orgId, memberId: target.id };
    const existing = await issueService.createIssue(actor, issueInput(orgId, tenant.project.id, {
      assigneeId: target.userId,
    }));
    const windowStart = toIsoTimestamp(new Date(Date.now() - 60_000));
    const payload = { title: "Notice", body: "A notice", href: "/", actorId: actor.userId };
    const prior = await notify(orgId, "comment_created", [target.userId], payload);
    const events: string[] = [];
    const detach = registerActivityListeners();
    const offSuspend = subscribe("member.suspended", () => { events.push("suspended"); });
    const offReinstate = subscribe("member.reinstated", () => { events.push("reinstated"); });
    try {
      const suspended = await memberService.suspendMember(actor, input);
      expect(suspended).toMatchObject({ status: "suspended", role: target.role, archivedAt: null });
      expect(await memberService.suspendMember(actor, input)).toEqual(suspended);
      expect(events).toEqual(["suspended"]);
      expect(await memberService.resolveActor(target.userId, orgId)).toBeNull();
      expect(await orgRepo.listOrgsForUser(target.userId)).toEqual([]);
      expect(await memberRepo.countActiveMembers(orgId)).toBe(4);
      expect((await usageRepo.recomputeUsage(orgId)).seatsUsed).toBe(4);
      expect((await memberService.listMembers(actor, { orgId, limit: 100, cursor: null })).items)
        .toEqual(expect.arrayContaining([expect.objectContaining({ id: target.id, status: "suspended" })]));
      expect((await issueRepo.findIssueById(orgId, existing.id))?.assigneeId).toBe(target.userId);
      const beforeCount = await issueRepo.countIssues(orgId, tenant.project.id);
      await expect(issueService.createIssue(actor, issueInput(orgId, tenant.project.id, {
        assigneeId: target.userId,
      }))).rejects.toBeInstanceOf(memberService.MemberSuspendedError);
      expect(await issueRepo.countIssues(orgId, tenant.project.id)).toBe(beforeCount);
      await expect(issueService.assignIssue(actor, { orgId, issueId: existing.id, assigneeId: target.userId }))
        .rejects.toBeInstanceOf(memberService.MemberSuspendedError);
      expect(await notify(orgId, "comment_created", [target.userId], payload)).toEqual([]);
      expect(await buildDigest(orgId, target.userId, windowStart, toIsoTimestamp(new Date()))).toBeNull();
      const comment = await commentService.createComment(actor, {
        orgId, issueId: existing.id, body: "Hello @member", parentId: null,
        mentionedUserIds: [target.userId],
      });
      expect(comment.mentionedUserIds).toEqual([]);
      const reinstated = await memberService.reinstateMember(actor, input);
      expect(reinstated.status).toBe("active");
      expect(await memberService.reinstateMember(actor, input)).toEqual(reinstated);
      expect(events).toEqual(["suspended", "reinstated"]);
      expect(await memberService.resolveActor(target.userId, orgId)).toEqual(tenant.actors.member);
      expect(await orgRepo.listOrgsForUser(target.userId)).toEqual([tenant.org]);
      expect((await buildDigest(orgId, target.userId, windowStart, toIsoTimestamp(new Date())))?.entries)
        .toEqual(expect.arrayContaining([expect.objectContaining({ notificationId: prior[0].id })]));
      const audit = await activityRepo.listActivity({ orgId, limit: 100, cursor: null });
      expect(audit.items.filter((row) => row.action === "member.suspended" || row.action === "member.reinstated"))
        .toEqual(expect.arrayContaining([
          expect.objectContaining({ action: "member.suspended", subjectKind: "member", subjectId: target.id, actorId: actor.userId }),
          expect.objectContaining({ action: "member.reinstated", subjectKind: "member", subjectId: target.id, actorId: actor.userId }),
        ]));
    } finally {
      detach(); offSuspend(); offReinstate();
    }
  });

  it("refuses self, higher roles, wrong tenants and removed members without changes", async () => {
    const tenant = await createTenant("suspension-guards");
    const other = await createTenant("suspension-other");
    const owner = (await memberRepo.findMember(tenant.org.id, tenant.userIds.owner))!;
    const viewer = (await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer))!;
    for (const operation of [memberService.suspendMember, memberService.reinstateMember]) {
      await expect(operation(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id })).rejects.toThrow(/yourself/);
      await expect(operation(tenant.actors.admin, { orgId: tenant.org.id, memberId: owner.id })).rejects.toThrow(/outranks/);
      await expect(operation(tenant.actors.owner, { orgId: other.org.id, memberId: viewer.id })).rejects.toBeInstanceOf(TenantScopeError);
      await expect(operation(tenant.actors.member, { orgId: tenant.org.id, memberId: viewer.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    }
    expect(await memberRepo.findMemberById(tenant.org.id, owner.id)).toEqual(owner);
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id });
    for (const operation of [memberService.suspendMember, memberService.reinstateMember]) {
      await expect(operation(tenant.actors.owner, { orgId: tenant.org.id, memberId: viewer.id })).rejects.toBeInstanceOf(NotFoundError);
    }
  });

  it("a suspended owner cannot justify demotion or removal of the remaining owner", async () => {
    const tenant = await createTenant("suspension-owner");
    const owner = (await memberRepo.findMember(tenant.org.id, tenant.userIds.owner))!;
    const admin = (await memberRepo.findMember(tenant.org.id, tenant.userIds.admin))!;
    await memberService.updateMemberRole(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id, role: "owner" });
    await memberService.suspendMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id });
    await expect(memberService.updateMemberRole(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id, role: "admin" }))
      .rejects.toThrow(/at least one owner/);
    await expect(memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: owner.id }))
      .rejects.toThrow(/at least one owner/);
    // Removing the suspended owner leaves the available owner in place.
    await memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId: admin.id });
  });
});
